import { createRouter, createWebHistory } from 'vue-router'
import { session } from './data/session'
import { users } from './data/users'

const routes = [
  {
    path: '/',
    name: 'Home',
    component: () => import('@/pages/Home.vue'),
  },
  {
    path: '/Register',
    name: 'Register',
    component: ()=> import('@/pages/Register.vue')
  },
  {
    path: '/Appointment',
    name: 'Appointment',
    component: ()=> import('@/pages/Appointment.vue')
  },
  {
    path: '/Booking_confirmation',
    name: 'Booking_confirmation',
    component: ()=> import('@/pages/Booking_confirmation.vue')
  },
  {
    path: '/Checkin',
    name: 'Checkin',
    component: ()=> import('@/pages/Checkin.vue')
  },
  {
    path: '/BookingSuccess',
    name: 'BookingSuccess',
    component: ()=> import('@/pages/BookingSuccess.vue')
  },
  {
    path: '/Payment',
    name: 'Payment',
    component: ()=> import('@/pages/Payment.vue')
  },
  // {
  //   path: '/Telecallers',
  //   name: 'Telecallers',
  //   component: ()=> import('@/pages/Telecallers_page.vue')
  // },
  {
    path: '/Waitlist',
    name: 'Waitlist',
    component: ()=> import('@/pages/Waitlist.vue')
  },
  {
    path: '/QueueSelection',
    name: 'QueueSelection',
    component: ()=> import('@/pages/QueueSelection.vue')
  },
  {
    path: '/TokenDisplay',
    name: 'TokenDisplay',
    component: ()=> import('@/pages/TokenDisplay.vue')
  },
  {
    path: '/practitioner_screen',
    name: 'practitioner_screen',
    component: ()=> import('@/pages/practitioner_screen.vue')
  },
  {
    path: '/bed_management',
    name: 'bed_management',
    component: ()=> import('@/pages/bed_management.vue')
  },
]

let router = createRouter({
  history: createWebHistory('/healthcare'),
  routes,
})

router.beforeEach(async (to, from, next) => {
  let isLoggedIn = session.isLoggedIn
  try {
    await users.promise
  } catch (error) {
    isLoggedIn = false
  }
  if (to.name === 'Login' && isLoggedIn) {
    next({ name: 'Home' })
  // } else if (to.name == 'Telecallers' && !isLoggedIn) {
  //   window.location.href = '/login?redirect-to=/healthcare/Telecallers'
  } else if (to.name == 'Waitlist' && !isLoggedIn) {
    window.location.href = '/login?redirect-to=/healthcare/Waitlist'
  } else if (to.name == 'practitioner_screen' && !isLoggedIn) {
    window.location.href = '/login?redirect-to=/healthcare/practitioner_screen'
  } else if (to.name == 'Checkin' && !isLoggedIn) {
    window.location.href = '/login?redirect-to=/healthcare/Checkin'
  } else if (to.name == 'TokenDisplay' && !isLoggedIn) {
    window.location.href = '/login?redirect-to=/healthcare/QueueSelection'
  } else if (!isLoggedIn) {
    window.location.href = '/login?redirect-to=/healthcare/'
  } else {
    next()
  }
})

export default router
